 if(o.command=="list"||o.command=="doctor"){std::cout<<"Backends:\n";for(auto& [name,s]:doc["backends"].items()){auto st=s.value("backend_status","?");std::cout<<"  "<<pad(name,8)<<pad(st,14)<<clip(s.value("reason",s.value("reason_message","")),72)<<'\n';}
  if(doc["devices"].empty())std::cout<<"Devices: none found\n";else{std::cout<<"Devices:\n";for(auto& d:doc["devices"]){std::string spec=device_spec(d);std::cout<<"  ["<<pad(d.value("backend",""),7)<<"] "<<pad(d.value("name","?"),36)<<"("<<device_alias(d)<<(spec.empty()?")":", "+spec+")")<<'\n';}}
  if(o.command=="doctor")for(auto& d:doc["devices"]){try{doc["capabilities"].push_back({{"device",d},{"capability",workers.at(d["backend"])->request("probe",{{"device",d}})}});}catch(const std::exception& e){doc["capabilities"].push_back({{"device",d},{"error",e.what()}});}}doc["summary"]={{"exit_code",0}};return write_outputs(o,doc)?0:4;}
 json selected=json::array();for(auto& d:doc["devices"]){if(o.device=="all"||o.device==d.value("id","")||o.device==d.value("alias",""))selected.push_back(d);}
 // Identity-based preference only: never deduplicate by name or enumeration index.
 if(o.backend=="auto"){json filtered=json::array();for(auto& d:selected){bool suppress=false;if(d["backend"]=="opencl"){auto identity=d.value("identity",json::object());for(auto& n:selected)if(n["backend"]!="opencl")for(auto key:{"uuid","luid","pci_bus_id"})if(identity.contains(key)&&!identity[key].is_null()&&identity[key]!=""&&n.value("identity",json::object()).value(key,json())==identity[key])suppress=true;}else{for(auto& candidate:selected)if(candidate["backend"]=="opencl")for(auto key:{"uuid","luid","pci_bus_id"}){auto identity=d.value("identity",json::object());if(identity.contains(key)&&!identity[key].is_null()&&identity[key]!=""&&candidate.value("identity",json::object()).value(key,json())==identity[key])d["opencl_fallback"]=candidate;}}if(!suppress)filtered.push_back(d);}selected=filtered;}
 if(selected.empty()&&o.device!="all"){std::string backend=o.backend;if(backend=="auto")backend=o.device.rfind("nvidia:",0)==0?"cuda":o.device.rfind("amd:",0)==0?"amd":o.device.rfind("intel:",0)==0?"intel":"opencl";selected.push_back({{"id",o.device},{"name","unavailable requested device"},{"backend",backend},{"backend_index",0},{"missing",true}});}
 bool failed=false,unavailable_items=selected.empty();size_t ok=0;if(selected.empty())std::cout<<"No GPU devices found. Run 'gpubench.exe doctor' for backend diagnostics.\n";
